      el3.innerHTML = '<div class="lib-wrap"><header class="lib-head"><b>\u56F3\u66F8\u9928</b><span class="lib-slot"></span></header><nav class="lib-tabs"></nav><main class="lib-main"><p class="lib-note">\u672C\u3092\u8AAD\u307F\u3053\u3093\u3067\u3044\u307E\u3059\u2026</p></main></div>';
